(function() {
    'use strict';

    // 外层容器
    const wrap = document.createElement('div');
    Object.assign(wrap.style, {
        position: 'fixed',
        top: '60px',
        right: '20px',
        zIndex: '999999',
        display: 'flex',
        flexDirection: 'column',
        gap: '6px'
    });

    // 公共按钮样式
    const getBtnStyle = (el) => {
        Object.assign(el.style, {
            padding: '8px 14px',
            borderRadius: '8px',
            border: 'none',
            background: '#2563eb',
            color: '#fff',
            fontSize: '14px',
            cursor: 'pointer',
            boxShadow: '0 2px 8px #0003'
        })
    };

    // 刷新按钮
    const btnRefresh = document.createElement('button');
    btnRefresh.innerText = '刷新';
    getBtnStyle(btnRefresh);
    btnRefresh.onclick = () => location.reload();
    btnRefresh.onmouseover = () => btnRefresh.style.background = '#1d4ed8';
    btnRefresh.onmouseout = () => btnRefresh.style.background = '#2563eb';

    // 返回按钮
    const btnBack = document.createElement('button');
    btnBack.innerText = '返回';
    getBtnStyle(btnBack);
    btnBack.onclick = () => history.back();
    btnBack.onmouseover = () => btnBack.style.background = '#1d4ed8';
    btnBack.onmouseout = () => btnBack.style.background = '#2563eb';

    // 装入容器
    wrap.appendChild(btnRefresh);
    wrap.appendChild(btnBack);
    document.body.appendChild(wrap);

})();

