    const QAAB_SALT = hexToBytes(
        "4dd4c2e6b83162090e52b3c7a6733ba4" +
        "1cb2462b829ab58a196b39db57177524" +
        "f49baf7f08e8d68d26a72e37c1a95a2f" +
        "1f05a51892aef2949732b62a38aadd58"
