    function hexToBytes(hex) {
        const text = String(hex || "").replace(/\s+/g, "");
        const bytes = new Uint8Array(text.length / 2);
        for (let i = 0; i < text.length; i += 2) bytes[i / 2] = parseInt(text.slice(i, i + 2), 16);
        return bytes;
    }

    function b64ToBytes(text) {
        const padded = String(text || "").trim().padEnd(text.length + (4 - text.length % 4) % 4, "=");
        const loose = padded.replace(/-/g, "+").replace(/_/g, "/");
        try {
            const binary = atob(loose);
            const bytes = new Uint8Array(binary.length);
            for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
            return bytes;
        } catch (e) { return new Uint8Array(0); }
    }

    function tryDecodeB64Url(text) {
        try {
            const bytes = b64ToBytes(text);
            const decoded = new TextDecoder().decode(bytes);
            return /^https?:\/\//i.test(decoded) ? decoded : null;
        } catch (e) { return null; }
    }

    async function sha512(bytes) { return new Uint8Array(await crypto.subtle.digest("SHA-512", bytes)); }

    async function deriveKeyIv(keySeedText) {
        const seed32 = b64ToBytes(keySeedText).slice(0, 32);
        const d1 = await sha512(seed32);
        const d2 = await sha512(new Uint8Array([...d1, ...QAAB_SALT]));
        return { key: d2.slice(0, 16), iv: d2.slice(16, 32) };
    }

    async function decryptAES(payload, key, iv) {
        const cryptoKey = await crypto.subtle.importKey("raw", key, "AES-CBC", false, ["decrypt"]);
        return new Uint8Array(await crypto.subtle.decrypt({ name: "AES-CBC", iv }, cryptoKey, payload));
    }

    async function decodeQAAB(token, keySeed) {
        const data = b64ToBytes(token);
        const derived = await deriveKeyIv(keySeed);
        const attempts = [];
        if (data.length >= 4 && data[0] === 0xa8 && data[1] === 0x00 && data[2] === 0x01 && data[3] === 0x00) {
            attempts.push({ payload: data.slice(4), key: derived.key, iv: derived.iv });
            attempts.push({ payload: data.slice(4), key: derived.iv, iv: derived.key });
            if (data.length > 36) {
                attempts.push({ payload: data.slice(36), key: derived.key, iv: data.slice(20, 36) });
                attempts.push({ payload: data.slice(36), key: derived.key, iv: derived.iv });
            }
        } else {
            attempts.push({ payload: data, key: derived.key, iv: derived.iv });
        }
        for (const attempt of attempts) {
            if (!attempt.payload.length || attempt.payload.length % 16 !== 0) continue;
            try {
                const plain = await decryptAES(attempt.payload, attempt.key, attempt.iv);
                const text = new TextDecoder("utf-8").decode(plain);
                if (/^https?:\/\//i.test(text)) return text;
            } catch (e) {}
        }
        return "";
    }

    async function decodeToken(token, keySeed) {
        if (!token || typeof token !== "string") return "";
        if (/^https?:\/\//i.test(token)) return token;
        const direct = tryDecodeB64Url(token);
        if (direct) return direct;
        if (!token.startsWith("qAAB") || !keySeed) return "";
        return decodeQAAB(token, keySeed);
    }

    function isNoWatermarkUrl(url) {
        if (!url || typeof url !== "string" || !/^https?:\/\//i.test(url)) return false;
        try {
            const parsed = new URL(url);
            return parsed.searchParams.get('cs') === '0' && parsed.searchParams.get('qs') === '13';
        } catch (e) { return false; }
    }

    function findDeep(obj, keys, depth = 0) {
        if (depth > 10 || !obj) return null;
        if (typeof obj === 'string') {
            for (const key of keys) {
                const match = obj.match(new RegExp(`["']${key}["']\\s*:\\s*["']([^"']+)`, 'i'));
                if (match) return match[1];
            }
            return null;
        }
        if (Array.isArray(obj)) {
            for (const item of obj) { const found = findDeep(item, keys, depth + 1); if (found) return found; }
            return null;
        }
        if (typeof obj !== 'object') return null;
        for (const key of keys) {
            if (typeof obj[key] === 'string' && obj[key].trim()) return obj[key].trim();
        }
        for (const val of Object.values(obj)) { const found = findDeep(val, keys, depth + 1); if (found) return found; }
        return null;
    }

    function findFplayUrls(obj, depth = 0, out = []) {
        if (depth > 12 || !obj) return out;
        if (typeof obj === 'string') {
            const matches = obj.match(/https?:\/\/[^"'<>\\\s]+\/video\/fplay\/[^"'<>\\\s]+/ig);
            if (matches) out.push(...matches);
            return out;
        }
        if (Array.isArray(obj)) { for (const item of obj) findFplayUrls(item, depth + 1, out); return out; }
        if (typeof obj !== 'object') return out;
        for (const val of Object.values(obj)) findFplayUrls(val, depth + 1, out);
        return out;
    }

    function findVid(obj, depth = 0) {
        if (depth > 10 || !obj) return null;
        if (typeof obj === "string") {
            const parsed = parseJson(obj);
            if (parsed !== obj) return findVid(parsed, depth + 1);
            return null;
        }
        if (Array.isArray(obj)) { for (const item of obj) { const found = findVid(item, depth + 1); if (found) return found; } }
        else if (typeof obj === "object") {
            const vid = obj.vid || obj.video_id;
            if (vid && typeof vid === "string" && vid.startsWith("v0")) return vid;
            for (const val of Object.values(obj)) { const found = findVid(val, depth + 1); if (found) return found; }
        }
        return null;
    }

    function parseJson(value) {
        if (typeof value !== 'string') return value;
