    async function resolveVideo(vid, msg) {
        let keySeed = "";
        let fallbackApi = "";
        let downloadUrl = "";

        const videoObj = findVideoObj(msg);
        if (videoObj) {
            downloadUrl = tryDecodeB64Url(videoObj.download_url || '') || videoObj.download_url || '';
            const model = typeof videoObj.video_model === 'string' ? parseJson(videoObj.video_model) : videoObj.video_model;
            keySeed = findDeep(model, ['key_seed']) || findDeep(videoObj, ['key_seed']) || "";
            fallbackApi = findDeep(model, ['fallback_api']) || findDeep(videoObj, ['fallback_api']) || "";
        }
        if (!fallbackApi) {
            const fplayUrls = findFplayUrls(msg);
            if (fplayUrls.length > 0) fallbackApi = fplayUrls[0];
        }

        if (downloadUrl && isNoWatermarkUrl(downloadUrl)) return { videoUrl: downloadUrl };

        if (fallbackApi && /^https?:\/\//i.test(fallbackApi)) {
            try {
                const url = new URL(fallbackApi);
