                const videoInfo = payload?.video_info || payload?.data?.video_info || payload;
                const data = videoInfo?.data || videoInfo;
                if (!data || typeof data !== "object") throw new Error("No video data");

                keySeed = keySeed || findDeep(payload, ['key_seed']);
                const videoList = data?.video_list || {};
                const entries = Object.keys(videoList).length ? Object.values(videoList) : [data];

                let best = null;
                let bestScore = -1;
                for (const entry of entries) {
                    if (!entry || typeof entry !== "object") continue;
                    const mainToken = entry.main_url || entry.play_url || "";
                    if (!mainToken) continue;
                    let videoUrl = await decodeToken(mainToken, keySeed);
                    if (!videoUrl) continue;
                    if (!isNoWatermarkUrl(videoUrl)) videoUrl = videoUrl.replace(/lr=[^&]+/g, "lr=video_gen_no_watermark");
                    const score = Number(entry.bitrate || 0) + (Number(entry.vwidth || 0) * Number(entry.vheight || 0));
                    if (score > bestScore) { bestScore = score; best = { videoUrl, backupUrl: entry.backup_url_1 || entry.backup_url || "" }; }
                }
                if (best) {
                    if (best.backupUrl) {
                        const decoded = await decodeToken(best.backupUrl, keySeed);
                        if (decoded) best.backupUrl = decoded;
                    }
                    return best;
                }
            } catch (e) {}
        }

        if (vid) {
