    async function readSSE(stream) {
        const reader = stream.getReader();
        const decoder = new TextDecoder();
        let buffer = "";
        try {
            while (true) {
                const { done, value } = await reader.read();
                if (done) return;
                buffer += decoder.decode(value, { stream: true });
                const parts = buffer.split("\n\n");
                buffer = parts.pop() || "";
                for (const part of parts) {
                    const match = part.match(/^data: (.+)$/m);
                    if (match) {
                        try {
                            const data = JSON.parse(match[1]);
                            const patchOps = data?.patch_op;
                            if (patchOps) {
                                const images = extractImgsFromPatch(patchOps);
                                if (images.length) {
                                    images.forEach(img => registerImg(img));
                                }
                                const msgId = String(data?.message_id || "").trim();
                                for (const op of patchOps) {
                                    const pv = op?.patch_value;
                                    if (!pv) continue;
                                    const id = String(pv.message_id || msgId || "").trim();
                                    if (!id || id === "0") continue;
                                    cacheMsg(pv, id);
                                    const vid = findVid(pv);
                                    if (vid) videoCache.set(id, vid);
                                }
                            }
                            setTimeout(() => { scanImgs(); scanVideos(); }, 300);
                        } catch(e) {}
                    }
                }
            }
        } catch(e) {}
    }

    function processMessages(messages) {
        if (!Array.isArray(messages)) return;
        for (const msg of messages) {
            cacheMsg(msg);
            const id = String(msg.message_id || "").trim();
            if (!id || id === "0") continue;
            const vid = findVid(msg);
