        }
        const images = extractImgs(messages);
        images.forEach(img => registerImg(img));
        setTimeout(() => { scanImgs(); scanVideos(); }, 300);
    }

    const originalFetch = window.fetch;
    const originalXHROpen = XMLHttpRequest.prototype.open;
    const originalXHRSend = XMLHttpRequest.prototype.send;

    window.fetch = function(...args) {
        const url = typeof args[0] === "string" ? args[0] : args[0]?.url;
        return originalFetch.apply(this, args).then(async (resp) => {
            const contentType = resp.headers.get("content-type") || "";

            if (typeof url === "string" && url.includes("chat/completion") && contentType.includes("text/event-stream")) {
                const [stream1, stream2] = resp.body.tee();
                readSSE(stream2);
                return new Response(stream1, { status: resp.status, statusText: resp.statusText, headers: resp.headers });
            }

            if (typeof url === "string" && (url.includes("chat/completion") || url.includes("chain/single")) && contentType.includes("json")) {
                try {
                    const clone = resp.clone();
                    const json = await clone.json();
                    processMessages(json?.downlink_body?.pull_singe_chain_downlink_body?.messages || json?.messages);
                } catch(e) {}
            }

            return resp;
        });
    };

    XMLHttpRequest.prototype.open = function(method, url, ...rest) { this._url = url; return originalXHROpen.call(this, method, url, ...rest); };
    XMLHttpRequest.prototype.send = function(...args) {
